class RealTimeBroker:
    def __init__(self):
        self.subscribers: Dict[str, List[Any]] = defaultdict(list)  # session_id -> [callback1, callback2, ...]
        self.lock = threading.RLock()

    def subscribe(self, session_id: str, callback):
        with self.lock:
            self.subscribers[session_id].append(callback)

    def unsubscribe(self, session_id: str, callback):
        with self.lock:
            if callback in self.subscribers[session_id]:
                self.subscribers[session_id].remove(callback)

    def broadcast(self, session_id: str, message: Dict):
        with self.lock:
            callbacks = list(self.subscribers.get(session_id, []))
        for callback in callbacks:
            try:
                callback(message)
            except Exception:
                pass  # Silently ignore callback errors

