            if team_id in session.teams:
                total += 1
                if session.state == GameState.FINISHED:
                    # Determine winner: highest score team
                    max_score = max(t.score for t in session.teams.values())
                    if session.teams[team_id].score == max_score:
                        wins += 1
        return wins / total if total > 0 else 0.0

